using Intranet.Entity;using Intranet.Service;using Microsoft.Extensions.Options;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.FileProviders;using System.Security.Claims;
namespace Intranet.Api.Tests;
public sealed class PcpRequirementsTests {
 [Theory][InlineData(true,true,true,0)][InlineData(false,true,true,1)][InlineData(true,false,true,1)][InlineData(true,true,false,1)][InlineData(false,false,false,3)]public void ListsEveryMissingRequirement(bool price,bool tariff,bool sheet,int count)=>Assert.Equal(count,new PcpRequirements(price,tariff,sheet,price?1m:null).Missing.Count);
 [Theory][InlineData(false,true,true,"Precio Comercial")][InlineData(true,false,true,"Status Tarifado")][InlineData(true,true,false,"Status Ficha Técnica")]
 public async Task SendRejectsBeforeSaving(bool price,bool tariff,bool sheet,string name){var repo=new Repo(new(price,tariff,sheet,price?1m:null));var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(IntranetLogin.GestionUserClaim,"PCP_TEST")],"Test"));var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer",EnableOrderRegistration=true,AllowAllAuthenticatedWrites=true}),new Env());var service=new PcpAnaliticasService(repo,new Ops(),identity,new RequestActor(user,true,false,false,true,"test"));var e=await Assert.ThrowsAsync<ArgumentException>(()=>service.Send(new(){Np="J1907",Variant="0",Sector="CS",RequestId=Guid.NewGuid()},default));Assert.Contains(name,e.Message);Assert.False(repo.Sent);}
 private sealed class Repo(PcpRequirements flags):IPcpAnaliticasRepository{public bool Sent;public Task<PcpRequirements> Requirements(string np,CancellationToken ct)=>Task.FromResult(flags);public Task<PcpEntry> Send(Guid requestId,PcpSelection snapshot,string user,CancellationToken ct){Sent=true;throw new InvalidOperationException();}public Task<PcpPage> Read(string? np,long? id,long? cursor,string? status,CancellationToken ct)=>throw new InvalidOperationException();}
 private sealed class Ops:IAnalisisRbOperationsRepository{public Task<AnalisisRbOperations?> Read(string np,string? variant,CancellationToken ct)=>throw new InvalidOperationException("No debe consultar procesos con requisitos faltantes");}
 private sealed class Env:IHostEnvironment{public string ApplicationName{get;set;}="Test";public string EnvironmentName{get;set;}="Production";public string ContentRootPath{get;set;}="";public IFileProvider ContentRootFileProvider{get;set;}=new NullFileProvider();}
}
